ALTER TABLE posts ADD COLUMN IF NOT EXISTS transport_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE posts ADD COLUMN IF NOT EXISTS area_lat DOUBLE PRECISION;
ALTER TABLE posts ADD COLUMN IF NOT EXISTS area_lng DOUBLE PRECISION;
CREATE TABLE IF NOT EXISTS search_alerts(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,keyword TEXT NOT NULL,city TEXT NOT NULL,category TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS search_alert_matches(alert_id TEXT NOT NULL REFERENCES search_alerts(id) ON DELETE CASCADE,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,PRIMARY KEY(alert_id,post_id));
CREATE TABLE IF NOT EXISTS post_questions(id TEXT PRIMARY KEY,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,asker_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,question TEXT NOT NULL,answer TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,answered_at TEXT);
CREATE TABLE IF NOT EXISTS material_needs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,title TEXT NOT NULL,description TEXT NOT NULL,city TEXT NOT NULL,deadline TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS need_offers(id TEXT PRIMARY KEY,need_id TEXT NOT NULL REFERENCES material_needs(id) ON DELETE CASCADE,donor_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,post_id TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,thread_id TEXT NOT NULL REFERENCES threads(id) ON DELETE CASCADE,negotiation_id TEXT NOT NULL REFERENCES negotiations(id) ON DELETE CASCADE,created_at TEXT NOT NULL,UNIQUE(need_id,post_id));
CREATE INDEX IF NOT EXISTS post_questions_post ON post_questions(post_id,created_at);
